<!doctype html>
<html><head><meta charset="utf-8"><title>{{ ucfirst($policy['policy_type']) }} privacy policy · {{ $organization?->name }}</title><style>body{font:15px Arial;color:#17212b;line-height:1.6;margin:50px}h1{color:#0e5963;border-bottom:2px solid #2dd4bf;padding-bottom:12px}h2{color:#0e5963;margin-top:28px}small{color:#607178}</style></head><body><h1>{{ $organization?->name }} {{ ucfirst($policy['policy_type']) }} Privacy Policy</h1><small>Effective {{ \Carbon\Carbon::parse($policy['effective_date'])->format('d M Y') }}</small><h2>1. Purpose</h2><p>This policy explains how {{ $organization?->name }} handles personal information in relation to its {{ $policy['policy_type'] }} activities.</p><h2>2. Personal information and purposes</h2><p>{{ $policy['processing_summary'] }}</p><h2>3. Retention and deletion</h2><p>{{ $policy['retention_summary'] }}</p><h2>4. Privacy contact</h2><p>Questions and requests may be sent to {{ $policy['contact_email'] }} or delivered to:</p><p>{{ $policy['contact_address'] }}</p><h2>5. Governance</h2><p>This policy should be reviewed periodically by the organisation's Data Protection Officer and updated when processing activities, legal requirements, or security measures change.</p></body></html>